{
  "states": [
    "Existing Session",
    "Terminated Dialog"
  ],
  "transitions": [
    {
      "from": "Existing Session",
      "event": "Receive non-2xx final response to re-INVITE (not 481/408/timeout)",
      "action": "Session parameters remain unchanged",
      "to": "Existing Session"
    },
    {
      "from": "Existing Session",
      "event": "Receive 481/408/Timeout on re-INVITE",
      "action": "Terminate the dialog",
      "to": "Terminated Dialog"
    },
    {
      "from": "Existing Session",
      "event": "Generate 2xx response and never receive ACK",
      "action": "Generate BYE to terminate the dialog",
      "to": "Terminated Dialog"
    },
    {
      "from": "Existing Session",
      "event": "Receive second INVITE before final response to first INVITE",
      "action": "Return 500 (Server Internal Error) response",
      "to": "Existing Session"
    },
    {
      "from": "Existing Session",
      "event": "Receive INVITE while sent INVITE in progress",
      "action": "Return 491 (Request Pending) response",
      "to": "Existing Session"
    },
    {
      "from": "Existing Session",
      "event": "Receive re-INVITE with changed session description",
      "action": "Adjust session parameters accordingly",
      "to": "Existing Session"
    }
  ]
}

